<template>
 <main class="admin-data-page"><header class="admin-page-heading"><div><h1>Phân quyền</h1><p>Chọn role, cấp quyền theo trang quản trị và thiết lập phạm vi dữ liệu theo đơn vị.</p></div><button class="btn btn-secondary" :disabled="busy || dirty" @click="load"><RefreshCw :size="16" /> Tải lại</button></header>
 <p v-if="error" class="admin-notice error" role="alert">{{ error }}</p>
 <div class="permission-layout">
 <section class="permission-panel role-panel"><header><h2>Vai trò</h2><small>{{ roles.length }} role</small></header><div class="panel-body"><div class="admin-search-box"><Search :size="16" /><input v-model="search" placeholder="Tìm role…" aria-label="Tìm role" /></div><button v-for="r in filteredRoles" :key="r.id" type="button" class="role-choice" :class="{selected:r.id===selected?.id}" :disabled="busy" @click="select(r)"><span><strong>{{ r.name }}</strong><small>{{ r.code }}</small><small>{{ r.userIds.length }} tài khoản</small></span><ChevronRight :size="16" /></button><p v-if="!filteredRoles.length" class="admin-empty">{{ loading?'Đang tải…':'Không có role phù hợp.' }}</p></div></section>
 <section class="permission-panel matrix-panel"><header><div><h2>Quyền theo trang</h2><small>{{ selected?.name || 'Chọn role bên trái' }}</small></div><label v-if="selected"><input type="checkbox" :checked="allPages" :indeterminate="grants.length>0 && !allPages" :disabled="readonly" @change="toggleAll(($event.target as HTMLInputElement).checked)" /> Chọn tất cả</label></header>
 <div class="panel-body matrix-body"><p class="permission-help">Quyền tạo, sửa hoặc xóa luôn kèm quyền xem. Chọn tên trang để cấp tất cả quyền của trang đó.</p>
 <table class="permission-matrix"><colgroup><col class="page-name-col" /><col v-for="a in actions" :key="a" class="action-col" /></colgroup><thead><tr><th>Trang quản trị</th><th v-for="a in actions" :key="a">{{ actionNames[a] }}</th></tr></thead><tbody><tr v-for="p in pages" :key="p.id"><td class="page-name-cell"><label class="page-choice"><input type="checkbox" :checked="pageChecked(p)" :indeterminate="pageMixed(p)" :disabled="readonly" :aria-label="`Toàn quyền trang ${p.name}`" @change="togglePage(p,($event.target as HTMLInputElement).checked)" /><span class="page-label">{{ p.name }}</span></label></td><td v-for="a in actions" :key="a"><input v-if="p.actions.includes(a)" type="checkbox" :checked="grants.includes(`${p.id}:${a}`)" :disabled="readonly" :aria-label="`${actionNames[a]} · ${p.name}`" @change="togglePermission(p,a,($event.target as HTMLInputElement).checked)" /><span v-else class="unsupported" aria-label="Không áp dụng">—</span></td></tr></tbody></table>
 <p v-if="selected?.protectedRole" class="permission-help">Role hệ thống được bảo vệ và có toàn quyền.</p><p v-if="selected?.assignedCoursesOnly" class="permission-help">Role chuyển đổi đang giữ phạm vi khóa được phân công. Lưu cấu hình mới sẽ chuyển sang phạm vi đơn vị.</p></div></section>
 <section class="permission-panel unit-panel"><header><div><h2>Phạm vi đơn vị</h2><small>{{ selected?.protectedRole?'Toàn hệ thống':`${scope.length} đơn vị đã chọn` }}</small></div></header><div class="panel-body"><p class="permission-help">Chọn cấp cha bao gồm các cấp con. Role được xem chương trình của đơn vị đã chọn và toàn bộ khóa học thuộc chương trình.</p><OrganizationCheckTree :model-value="selected?.protectedRole?units.map(u=>u.id):scope" :units="units" :disabled="readonly" @update:model-value="scope=$event" /><p v-if="!scope.length && selected && !selected.protectedRole" class="scope-empty">Chưa chọn đơn vị: chưa có phạm vi dữ liệu đào tạo.</p></div></section>
 </div>
 <footer v-if="selected" class="permission-footer"><span>{{ dirty?'Có thay đổi chưa lưu':'Cấu hình đã lưu' }} · {{ grants.length }} quyền</span><div class="admin-row-actions"><button class="btn btn-secondary" :disabled="!dirty || busy" @click="reset">Hủy thay đổi</button><button v-if="user.can('permissions','update')" class="btn btn-primary" :disabled="readonly || !dirty" @click="save">{{ busy?'Đang lưu…':'Lưu phân quyền' }}</button></div></footer>
 <ConfirmModal :open="!!pending" title="Chuyển role?" message="Các thay đổi chưa lưu sẽ bị bỏ. Tiếp tục chọn role khác?" confirm-label="Bỏ thay đổi và chuyển" @cancel="pending=null" @confirm="confirmSelect" />
 </main>
</template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {RefreshCw,Search,ChevronRight} from 'lucide-vue-next';import {roleApi,type AccessRole,type AdminPage} from '../api/roleApi';import type {OrganizationUnit} from '../types/organization';import {useUserStore} from '../stores/userStore';import {showToast} from '../utils/toast';import OrganizationCheckTree from '../components/OrganizationCheckTree.vue';import ConfirmModal from '../components/ConfirmModal.vue';
const user=useUserStore(),route=useRoute();const roles=ref<AccessRole[]>([]),pages=ref<AdminPage[]>([]),units=ref<OrganizationUnit[]>([]),selected=ref<AccessRole|null>(null),pending=ref<AccessRole|null>(null),grants=ref<string[]>([]),scope=ref<string[]>([]),search=ref(''),busy=ref(false),loading=ref(false),error=ref('');const actions=['create','read','update','delete'];const actionNames:Record<string,string>={create:'Tạo',read:'Xem',update:'Sửa',delete:'Xóa'};
const filteredRoles=computed(()=>roles.value.filter(r=>`${r.name} ${r.code}`.toLocaleLowerCase('vi').includes(search.value.toLocaleLowerCase('vi'))));const normalized=(values:string[])=>[...values].sort().join('|');const dirty=computed(()=>!!selected.value&&(normalized(grants.value)!==normalized(selected.value.permissions)||normalized(scope.value)!==normalized(selected.value.unitIds)));const readonly=computed(()=>busy.value||!selected.value||selected.value.protectedRole||!user.can('permissions','update'));
const allPages=computed(()=>!!pages.value.length&&pages.value.every(pageChecked));function pageChecked(p:AdminPage){return p.actions.every(a=>grants.value.includes(`${p.id}:${a}`))}function pageMixed(p:AdminPage){return !pageChecked(p)&&p.actions.some(a=>grants.value.includes(`${p.id}:${a}`))}
function togglePage(p:AdminPage,yes:boolean){const set=new Set(grants.value);p.actions.forEach(a=>yes?set.add(`${p.id}:${a}`):set.delete(`${p.id}:${a}`));grants.value=[...set]}
function toggleAll(yes:boolean){grants.value=yes?pages.value.flatMap(p=>p.actions.map(a=>`${p.id}:${a}`)):[]}
function togglePermission(p:AdminPage,a:string,yes:boolean){const set=new Set(grants.value);if(yes){set.add(`${p.id}:${a}`);set.add(`${p.id}:read`)}else if(a==='read'){p.actions.forEach(action=>set.delete(`${p.id}:${action}`))}else set.delete(`${p.id}:${a}`);grants.value=[...set]}
function apply(r:AccessRole){selected.value=r;grants.value=[...r.permissions];scope.value=[...r.unitIds]}
function select(r:AccessRole){if(r.id===selected.value?.id)return;if(dirty.value)pending.value=r;else apply(r)}function confirmSelect(){if(pending.value)apply(pending.value);pending.value=null}function reset(){if(selected.value)apply(selected.value)}
async function load(){loading.value=true;error.value='';try{const data=await Promise.all([roleApi.options(),roleApi.pages(),roleApi.units()]);[roles.value,pages.value,units.value]=data;const r=roles.value.find(r=>r.id===(route.query.role || selected.value?.id)) || roles.value.find(r=>!r.protectedRole) || roles.value[0];if(r)apply(r);else selected.value=null;}catch(e:any){error.value=e.response?.data?.message || 'Không thể tải cấu hình phân quyền.'}finally{loading.value=false}}
async function save(){if(!selected.value)return;busy.value=true;error.value='';try{const r=await roleApi.grants(selected.value,grants.value,scope.value);roles.value=roles.value.map(x=>x.id===r.id?r:x);apply(r);await user.refreshAccess();showToast('Đã lưu phân quyền và cập nhật quyền truy cập','success')}catch(e:any){error.value=e.response?.data?.message || 'Không thể lưu phân quyền.'}finally{busy.value=false}}
onMounted(load);
</script>
<style scoped>
.admin-page-heading .btn{display:flex;align-items:center;gap:.4rem}.permission-layout{display:grid;grid-template-columns:minmax(205px,.8fr) minmax(490px,1.8fr) minmax(285px,1fr);gap:18px;align-items:stretch}.permission-panel{border:1px solid #dde5ec;border-radius:10px;background:white;min-width:0;overflow:hidden}.permission-panel>header{padding:18px;border-bottom:1px solid #e3eaf0;min-height:84px;display:flex;align-items:center;justify-content:space-between;gap:8px}.permission-panel h2{font-size:1rem;margin:0 0 4px}.permission-panel small{color:var(--text-muted,#758399);font-size:.76rem}.panel-body{padding:16px}.role-panel .panel-body{max-height:640px;overflow:auto}.role-choice{width:100%;text-align:left;display:flex;align-items:center;justify-content:space-between;gap:8px;background:white;border:1px solid transparent;border-radius:7px;padding:13px 10px;margin-top:6px;cursor:pointer;color:#253449}.role-choice strong,.role-choice small{display:block;overflow-wrap:anywhere}.role-choice small{margin-top:4px}.role-choice.selected{background:#eaf4ef;border-color:#c7dfd4;color:#00634b}.permission-help{font-size:.79rem;line-height:1.6;color:var(--text-muted);margin:0 0 16px}.permission-matrix{width:100%;table-layout:fixed;border-collapse:collapse}.page-name-col{width:48%}.action-col{width:13%}.permission-matrix th{background:#f7f9fb;font-size:.8rem;text-align:center;padding:12px 4px;color:var(--text-muted)}.permission-matrix th:first-child{text-align:left;padding-left:10px}.permission-matrix td{padding:15px 4px;text-align:center;border-bottom:1px solid #e3eaf0}.permission-matrix .page-name-cell{text-align:left;padding-left:10px}.page-choice{display:flex;align-items:center;gap:10px;min-width:0}.page-label{display:block;min-width:0;flex:1;font-weight:600;font-size:.84rem;line-height:1.5;color:#263449;overflow-wrap:break-word;white-space:normal}.permission-layout input[type=checkbox]{width:16px;height:16px;flex:0 0 16px;accent-color:#00634b;cursor:pointer}.permission-panel header label{font-size:.75rem;white-space:nowrap;display:flex;gap:5px;align-items:center}.unsupported{color:#b5bdc7}.scope-empty{background:#fff8e8;padding:10px;border-radius:6px;font-size:.8rem;color:#8b681c}.permission-footer{position:sticky;bottom:0;background:white;border-top:1px solid #dde5ec;display:flex;align-items:center;justify-content:space-between;padding:16px 0;margin-top:18px;gap:10px;z-index:2}.permission-footer>span{color:var(--text-muted);font-size:.83rem}@media(max-width:1250px){.permission-layout{grid-template-columns:210px minmax(470px,1fr)}.unit-panel{grid-column:2}.role-panel{grid-row:1/3}}@media(max-width:850px){.permission-layout{display:flex;flex-direction:column}.matrix-body{overflow-x:auto}.permission-matrix{min-width:470px}.permission-footer{flex-wrap:wrap}}
</style>
